WITH "__duckstream_0" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, make_timestamp(CAST(((CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END)::HUGEINT + CAST(1860000000 AS BIGINT)) AS BIGINT)) AS c3 FROM (SELECT "id" AS c0, "a" AS c1, "b" AS c2 FROM "instants") t),
"__duckstream_1" AS (SELECT t.c0 AS c0, t.c3 AS c1, CAST((CAST(((CASE WHEN t.c2 IS NULL OR isfinite(t.c2) THEN epoch_us(t.c2) ELSE error('finite TIMESTAMP required') END)::HUGEINT - (CASE WHEN t.c1 IS NULL OR isfinite(t.c1) THEN epoch_us(t.c1) ELSE error('finite TIMESTAMP required') END)::HUGEINT) AS BIGINT) // 1000000) AS INTEGER) AS c2, ('tick' || CAST(t.c0 AS VARCHAR)) AS c3 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3 FROM "__duckstream_0" v) t)
SELECT CAST(result.c0 AS INTEGER) AS "id", CAST(result.c1 AS TIMESTAMP) AS "next_epoch", CAST(result.c2 AS INTEGER) AS "seconds", CAST(result.c3 AS VARCHAR) AS "label" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3 FROM "__duckstream_1" v) result;
